pub fn run(argv: &[String]) -> Result<u8, String> {
    let prog = if argv.is_empty() { "executable".to_string() } else { ProgName::from_argv0(&argv[0]) };
    // mdBook always shows the binary name in help/usage
    let prog_name = prog.clone();

    // Handle top-level: first scan for --help, --version, subcommand
    let mut args = argv[1..].iter().peekable();

    // Main-level options before subcommand
    while let Some(a) = args.peek() {
        let s = a.as_str();
        if s == "-h" || s == "--help" {
            print_main_help(&prog_name);
            return Ok(0);
        } else if s == "-V" || s == "--version" {
            println!("mdbook v{}", VERSION);
            return Ok(0);
        } else if s.starts_with("--") || (s.starts_with("-") && s != "-") {
            let usage = format!("Usage: {} [COMMAND]", prog_name);
            clap_error(&format!("unexpected argument '{}' found", s), &usage);
        } else {
            break;
        }
    }

    let sub = match args.next() {
        Some(s) => s.clone(),
        None => {
            print_main_help(&prog_name);
            return Ok(2);
        }
    };

    let rest: Vec<String> = args.cloned().collect();

    match sub.as_str() {
        "init" => {
            let args = parse_init(&prog_name, &rest)?;
            crate::init::run(args)?;
            Ok(0)
        }
        "build" => {
            let args = parse_build(&prog_name, &rest)?;
            crate::build::run_build(args)
        }
        "test" => {
            let args = parse_test(&prog_name, &rest)?;
            crate::build::run_test(args)
        }
        "clean" => {
            let args = parse_clean(&prog_name, &rest)?;
            crate::clean::run(args)
        }
        "completions" => {
            let shell = parse_completions(&prog_name, &rest)?;
            crate::completions::run(shell);
            Ok(0)
        }
        "watch" => {
            let args = parse_watch(&prog_name, &rest)?;
            crate::build::run_watch(args)
        }
        "serve" => {
            let args = parse_serve(&prog_name, &rest)?;
            crate::build::run_serve(args)
        }
        "help" => {
            // `help [COMMAND...]` - print help of subcommand
            if let Some(first) = rest.first() {
                print_sub_help(&prog_name, first, "help")?;
            } else {
                print_main_help(&prog_name);
            }
            Ok(0)
        }
        _ => {
            let usage = format!("Usage: {} [COMMAND]", prog_name);
            clap_error(&format!("unrecognized subcommand '{}'", sub), &usage);
        }
    }
}

fn print_sub_help(prog: &str, sub: &str, parent: &str) -> Result<(), String> {
    match sub {
        "init" => print_init_help(prog),
        "build" => print_build_help(prog),
        "test" => print_test_help(prog),
        "clean" => print_clean_help(prog),
        "completions" => print_completions_help(prog),
        "watch" => print_watch_help(prog),
        "serve" => print_serve_help(prog),
        "help" => print_help_help(prog),
        _ => {
            // Error: unrecognized subcommand of parent command
            let usage = match parent {
                "help" => format!("Usage: {} [COMMAND]", prog),
                _ => format!("Usage: {} [COMMAND]", prog),
            };
            clap_error(&format!("unrecognized subcommand '{}'", sub), &usage);
        }
    }
    Ok(())
}

// -------- helpers --------
fn require_value(name: &str, iter: &mut std::iter::Peekable<std::slice::Iter<String>>, extra_possible: Option<&str>) -> String {
    match iter.next() {
        Some(v) => v.clone(),
        None => {
            eprintln!("error: a value is required for '{}' but none was supplied", name);
            if let Some(p) = extra_possible {
                eprintln!("  [possible values: {}]", p);
            }
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

fn take_value_or_attached<'a>(arg: &'a str, long_prefix: &str, iter: &mut std::iter::Peekable<std::slice::Iter<String>>, option_display: &str, possible: Option<&str>) -> String {
    if let Some(eq_pos) = arg.find('=') {
        let pref = &arg[..eq_pos];
        if pref == long_prefix {
            return arg[eq_pos+1..].to_string();
        }
    }
    require_value(option_display, iter, possible)
}

// -------- init --------
fn parse_init(prog: &str, rest: &[String]) -> Result<InitArgs, String> {
    let usage = format!("Usage: {} init [OPTIONS] [dir]", prog);
    let mut args = InitArgs {
        dir: None,
        theme: false,
        force: false,
        title: None,
        ignore: None,
    };
    let mut iter = rest.iter().peekable();
    let mut positional: Vec<String> = Vec::new();
    let mut pass_through = false;
    while let Some(a) = iter.next() {
        let s: &str = a.as_str();
        if pass_through {
            positional.push(s.to_string());
            continue;
        }
        if s == "--" { pass_through = true; continue; }
        if s == "-h" || s == "--help" { print_init_help(prog); std::process::exit(0); }
        if s == "-V" || s == "--version" { println!("mdbook-init v{}", VERSION); std::process::exit(0); }
        if s == "--theme" { args.theme = true; continue; }
        if s == "--force" { args.force = true; continue; }
        if s == "--title" || s.starts_with("--title=") {
            let v = if let Some(eq) = s.find('=') { s[eq+1..].to_string() } else {
                match iter.next() { Some(x) => x.clone(), None => {
                    eprintln!("error: a value is required for '--title <title>' but none was supplied\n");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }}
            };
            args.title = Some(v);
            continue;
        }
        if s == "--ignore" || s.starts_with("--ignore=") {
            let v = if let Some(eq) = s.find('=') { s[eq+1..].to_string() } else {
                match iter.next() { Some(x) => x.clone(), None => {
                    eprintln!("error: a value is required for '--ignore <ignore>' but none was supplied");
                    eprintln!("  [possible values: none, git]\n");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }}
            };
            match v.as_str() {
                "none" => args.ignore = Some(Ignore::None),
                "git" => args.ignore = Some(Ignore::Git),
                other => {
                    eprintln!("error: invalid value '{}' for '--ignore <ignore>'", other);
                    eprintln!("  [possible values: none, git]\n");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
            continue;
        }
        if s.starts_with("--") || (s.starts_with("-") && s != "-") {
            eprintln!("error: unexpected argument '{}' found\n", s);
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'\n", s, s);
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
        positional.push(s.to_string());
    }
    if positional.len() > 1 {
        eprintln!("error: unexpected argument '{}' found\n", positional[1]);
        eprintln!("{}\n", usage);
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if let Some(dir) = positional.into_iter().next() {
        args.dir = Some(PathBuf::from(dir));
    }
    Ok(args)
}

fn parse_build(prog: &str, rest: &[String]) -> Result<BuildArgs, String> {
    parse_build_like(prog, "build", rest, true)
        .map(|(dir, dest, open, _, _, _, _)| BuildArgs { dir, dest_dir: dest, open })
}

fn parse_test(prog: &str, rest: &[String]) -> Result<TestArgs, String> {
    let usage = format!("Usage: {} test [OPTIONS] [dir]", prog);
    let mut dir: Option<PathBuf> = None;
    let mut dest_dir: Option<PathBuf> = None;
    let mut chapter: Option<String> = None;
    let mut library_path: Option<String> = None;
    let mut iter = rest.iter().peekable();
    let mut positional = Vec::new();
    let mut pass_through = false;
    while let Some(a) = iter.next() {
        let s: &str = a.as_str();
        if pass_through { positional.push(s.to_string()); continue; }
        if s == "--" { pass_through = true; continue; }
        if s == "-h" || s == "--help" { print_test_help(prog); std::process::exit(0); }
        if s == "-V" || s == "--version" { println!("mdbook-test v{}", VERSION); std::process::exit(0); }
        if s == "-d" || s == "--dest-dir" || s.starts_with("--dest-dir=") {
            let v = opt_val(s, "-d", "--dest-dir", "--dest-dir <dest-dir>", &mut iter, None);
            dest_dir = Some(PathBuf::from(v));
            continue;
        }
        if s == "-c" || s == "--chapter" || s.starts_with("--chapter=") {
            let v = opt_val(s, "-c", "--chapter", "--chapter <chapter>", &mut iter, None);
            chapter = Some(v);
            continue;
        }
        if s == "-L" || s == "--library-path" || s.starts_with("--library-path=") {
