fn take_value_or_attached<'a>(arg: &'a str, long_prefix: &str, iter: &mut std::iter::Peekable<std::slice::Iter<String>>, option_display: &str, possible: Option<&str>) -> String {
    if let Some(eq_pos) = arg.find('=') {
        let pref = &arg[..eq_pos];
        if pref == long_prefix {
            return arg[eq_pos+1..].to_string();
        }
    }
    require_value(option_display, iter, possible)
}

