fn parse_init(prog: &str, rest: &[String]) -> Result<InitArgs, String> {
    let usage = format!("Usage: {} init [OPTIONS] [dir]", prog);
    let mut args = InitArgs {
        dir: None,
        theme: false,
        force: false,
        title: None,
        ignore: None,
    };
    let mut iter = rest.iter().peekable();
    let mut positional: Vec<String> = Vec::new();
    let mut pass_through = false;
    while let Some(a) = iter.next() {
        let s: &str = a.as_str();
        if pass_through {
            positional.push(s.to_string());
            continue;
        }
        if s == "--" { pass_through = true; continue; }
        if s == "-h" || s == "--help" { print_init_help(prog); std::process::exit(0); }
        if s == "-V" || s == "--version" { println!("mdbook-init v{}", VERSION); std::process::exit(0); }
        if s == "--theme" { args.theme = true; continue; }
        if s == "--force" { args.force = true; continue; }
        if s == "--title" || s.starts_with("--title=") {
            let v = if let Some(eq) = s.find('=') { s[eq+1..].to_string() } else {
                match iter.next() { Some(x) => x.clone(), None => {
                    eprintln!("error: a value is required for '--title <title>' but none was supplied\n");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }}
            };
            args.title = Some(v);
            continue;
        }
        if s == "--ignore" || s.starts_with("--ignore=") {
            let v = if let Some(eq) = s.find('=') { s[eq+1..].to_string() } else {
                match iter.next() { Some(x) => x.clone(), None => {
                    eprintln!("error: a value is required for '--ignore <ignore>' but none was supplied");
                    eprintln!("  [possible values: none, git]\n");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }}
            };
            match v.as_str() {
                "none" => args.ignore = Some(Ignore::None),
                "git" => args.ignore = Some(Ignore::Git),
                other => {
                    eprintln!("error: invalid value '{}' for '--ignore <ignore>'", other);
                    eprintln!("  [possible values: none, git]\n");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
            continue;
        }
        if s.starts_with("--") || (s.starts_with("-") && s != "-") {
            eprintln!("error: unexpected argument '{}' found\n", s);
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'\n", s, s);
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
        positional.push(s.to_string());
    }
    if positional.len() > 1 {
        eprintln!("error: unexpected argument '{}' found\n", positional[1]);
        eprintln!("{}\n", usage);
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if let Some(dir) = positional.into_iter().next() {
        args.dir = Some(PathBuf::from(dir));
    }
    Ok(args)
}

