fn parse_completions(prog: &str, rest: &[String]) -> Result<Shell, String> {
    let mut iter = rest.iter().peekable();
    let mut shell: Option<String> = None;
    while let Some(a) = iter.next() {
        let s: &str = a.as_str();
        if s == "-h" || s == "--help" { print_completions_help(prog); std::process::exit(0); }
        if s == "-V" || s == "--version" { println!("mdbook-completions v{}", VERSION); std::process::exit(0); }
        if s.starts_with("-") && s != "-" {
            let usage = format!("Usage: {} completions <SHELL>", prog);
            eprintln!("error: unexpected argument '{}' found\n", s);
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
        if shell.is_none() { shell = Some(s.to_string()); } else {
            let usage = format!("Usage: {} completions <SHELL>", prog);
            eprintln!("error: unexpected argument '{}' found\n", s);
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
    let s = match shell {
        Some(s) => s,
        None => {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  <SHELL>\n");
            eprintln!("Usage: {} completions <SHELL>\n", prog);
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    };
    match s.as_str() {
        "bash" => Ok(Shell::Bash),
        "elvish" => Ok(Shell::Elvish),
        "fish" => Ok(Shell::Fish),
        "powershell" => Ok(Shell::PowerShell),
        "zsh" => Ok(Shell::Zsh),
        other => {
            eprintln!("error: invalid value '{}' for '<SHELL>'", other);
            eprintln!("  [possible values: bash, elvish, fish, powershell, zsh]\n");
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

