fn parse_build_like(
    prog: &str, sub: &str, rest: &[String], _build: bool,
) -> Result<(Option<PathBuf>, Option<PathBuf>, bool, Watcher, Option<String>, Option<String>, ()), String> {
    let usage = format!("Usage: {} {} [OPTIONS] [dir]", prog, sub);
    let mut dir: Option<PathBuf> = None;
    let mut dest_dir: Option<PathBuf> = None;
    let mut open = false;
    let mut watcher = Watcher::Poll;
    let mut hostname: Option<String> = None;
    let mut port: Option<String> = None;
    let mut iter = rest.iter().peekable();
    let mut positional = Vec::new();
    let mut pass_through = false;
    while let Some(a) = iter.next() {
        let s: &str = a.as_str();
        if pass_through { positional.push(s.to_string()); continue; }
        if s == "--" { pass_through = true; continue; }
        if s == "-h" || s == "--help" {
            match sub {
                "build" => print_build_help(prog),
                "watch" => print_watch_help(prog),
                "serve" => print_serve_help(prog),
                _ => print_build_help(prog),
            }
            std::process::exit(0);
        }
        if s == "-V" || s == "--version" {
            println!("mdbook-{} v{}", sub, VERSION);
            std::process::exit(0);
        }
        if s == "-d" || s == "--dest-dir" || s.starts_with("--dest-dir=") {
            let v = opt_val(s, "-d", "--dest-dir", "--dest-dir <dest-dir>", &mut iter, None);
            dest_dir = Some(PathBuf::from(v));
            continue;
        }
        if s == "-o" || s == "--open" { open = true; continue; }
        if (sub == "watch" || sub == "serve") && (s == "--watcher" || s.starts_with("--watcher=")) {
            let v = opt_val(s, "", "--watcher", "--watcher <watcher>", &mut iter, Some("poll, native"));
            match v.as_str() {
                "poll" => watcher = Watcher::Poll,
                "native" => watcher = Watcher::Native,
                other => {
                    eprintln!("error: invalid value '{}' for '--watcher <watcher>'", other);
                    eprintln!("  [possible values: poll, native]\n");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
            continue;
        }
        if sub == "serve" && (s == "-n" || s == "--hostname" || s.starts_with("--hostname=")) {
            let v = opt_val(s, "-n", "--hostname", "--hostname <hostname>", &mut iter, None);
            hostname = Some(v);
            continue;
        }
        if sub == "serve" && (s == "-p" || s == "--port" || s.starts_with("--port=")) {
            let v = opt_val(s, "-p", "--port", "--port <port>", &mut iter, None);
            port = Some(v);
            continue;
        }
