use std::io::{self, Write, BufRead};
use std::path::{Path, PathBuf};

pub fn now_log_prefix() -> String {
    // Format: 2026-05-07 21:27:15
    let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap();
    let secs = now.as_secs() as i64;
    format_unix_secs(secs)
}

/// Convert unix epoch seconds (UTC) to "YYYY-MM-DD HH:MM:SS"
fn format_unix_secs(secs: i64) -> String {
    // Days since 1970-01-01
    let days = secs.div_euclid(86400);
    let secs_in_day = secs.rem_euclid(86400);
    let hour = secs_in_day / 3600;
    let min = (secs_in_day % 3600) / 60;
    let sec = secs_in_day % 60;
    let (y, m, d) = civil_from_days(days);
    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", y, m, d, hour, min, sec)
}

/// Convert days since 1970-01-01 to (year, month, day) (proleptic Gregorian).
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    // Algorithm by Howard Hinnant
    let z = z + 719468;
    let era = if z >= 0 { z / 146097 } else { (z - 146096) / 146097 };
    let doe = (z - era * 146097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153;                      // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { (mp + 3) as u32 } else { (mp - 9) as u32 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

pub fn log_info(mod_path: &str, msg: &str) {
    eprintln!("{} [INFO] ({}): {}", now_log_prefix(), mod_path, msg);
}

pub fn log_error(mod_path: &str, msg: &str) {
    eprintln!("{} [ERROR] ({}): {}", now_log_prefix(), mod_path, msg);
}

pub fn absolutize(p: &Path) -> PathBuf {
    if p.is_absolute() {
        p.to_path_buf()
    } else {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let joined = cwd.join(p);
        normalize(&joined)
    }
}

fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for comp in p.components() {
        match comp {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                if !out.pop() {
                    out.push("..");
                }
            }
            other => out.push(other.as_os_str()),
        }
    }
    if out.as_os_str().is_empty() {
        out.push(".");
    }
    out
}

/// Prompt the user for input with a given question and read a line from stdin.
pub fn prompt(question: &str) -> String {
    println!("{}", question);
    io::stdout().flush().ok();
    let stdin = io::stdin();
    let mut line = String::new();
    stdin.lock().read_line(&mut line).ok();
    if line.ends_with('\n') { line.pop(); }
    if line.ends_with('\r') { line.pop(); }
    line
}

/// Try to read `git config user.name` from available sources.
pub fn git_user_name(in_dir: &Path) -> Option<String> {
    // Try running `git config user.name` in the directory if git is available
    // Avoid shelling out; instead, parse ~/.gitconfig and /etc/gitconfig
    // Actually, since we can't rely on git binary in every env, try parsing config
    // First look for repo config at <in_dir>/.git/config walking up.
    let mut cur: Option<PathBuf> = Some(in_dir.to_path_buf());
    while let Some(d) = cur {
        let cfg = d.join(".git/config");
        if cfg.exists() {
            if let Some(name) = parse_gitconfig(&cfg).and_then(|kv| kv.get("user.name").cloned()) {
                return Some(name);
            }
            break;
        }
        cur = d.parent().map(|p| p.to_path_buf());
    }
    // Global
    if let Some(home) = std::env::var_os("HOME") {
        let p = PathBuf::from(&home).join(".gitconfig");
        if let Some(kv) = parse_gitconfig(&p) {
            if let Some(n) = kv.get("user.name") { return Some(n.clone()); }
        }
        let p2 = PathBuf::from(&home).join(".config/git/config");
        if let Some(kv) = parse_gitconfig(&p2) {
            if let Some(n) = kv.get("user.name") { return Some(n.clone()); }
        }
    }
    // System
    let p3 = PathBuf::from("/etc/gitconfig");
    if let Some(kv) = parse_gitconfig(&p3) {
        if let Some(n) = kv.get("user.name") { return Some(n.clone()); }
    }
    None
}

fn parse_gitconfig(path: &Path) -> Option<std::collections::HashMap<String, String>> {
    let text = std::fs::read_to_string(path).ok()?;
    let mut out = std::collections::HashMap::new();
    let mut section = String::new();
    for line in text.lines() {
        let l = line.trim();
        if l.is_empty() || l.starts_with('#') || l.starts_with(';') { continue; }
        if l.starts_with('[') && l.ends_with(']') {
            let inner = &l[1..l.len()-1];
            // e.g. [user] or [user "name"]
            if let Some(idx) = inner.find(' ') {
                let head = &inner[..idx];
                let sub = inner[idx+1..].trim();
                let sub = sub.trim_matches('"');
                section = format!("{}.{}", head.trim(), sub);
            } else {
                section = inner.trim().to_string();
            }
            continue;
        }
        if let Some(eq) = l.find('=') {
            let key = l[..eq].trim();
            let mut val = l[eq+1..].trim().to_string();
            // strip surrounding quotes
            if val.starts_with('"') && val.ends_with('"') && val.len() >= 2 {
                val = val[1..val.len()-1].to_string();
            }
            out.insert(format!("{}.{}", section, key), val);
        }
    }
    Some(out)
}

/// Format bytes like mdBook does: e.g. "20B", "1.89MiB", "87B"
pub fn format_bytes(bytes: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = 1024 * 1024;
    const GIB: u64 = 1024 * 1024 * 1024;
    const TIB: u64 = 1024u64.pow(4);
    if bytes < KIB {
        format!("{}B", bytes)
    } else if bytes < MIB {
        format!("{}KiB", format_decimal(bytes as f64 / KIB as f64))
    } else if bytes < GIB {
        format!("{}MiB", format_decimal(bytes as f64 / MIB as f64))
    } else if bytes < TIB {
        format!("{}GiB", format_decimal(bytes as f64 / GIB as f64))
    } else {
        format!("{}TiB", format_decimal(bytes as f64 / TIB as f64))
    }
}

fn format_decimal(v: f64) -> String {
    // format like "1.89" (2 decimal places, no trailing zeros? Actually mdbook shows 2 decimals always)
    // The example shows "1.89MiB". Let's use 2 decimal places always.
    format!("{:.2}", v)
}
