    } else {
        let t = util::prompt("What title would you like to give the book? ");
        if t.is_empty() { None } else { Some(t) }
    };

    // Determine authors from git config
    let authors = util::git_user_name(&dir);

    // Write book.toml
    let book_toml_path = dir.join("book.toml");
    if !book_toml_path.exists() {
        let mut content = String::new();
        content.push_str("[book]\n");
        // authors
        match &authors {
            Some(a) => content.push_str(&format!("authors = [{}]\n", toml_escape_str(a).into_iter().map(|s| format!("\"{}\"", s)).collect::<Vec<_>>().join(", "))),
            None => content.push_str("authors = []\n"),
        }
        content.push_str("language = \"en\"\n");
        content.push_str("src = \"src\"\n");
        if let Some(t) = &title_line {
            content.push_str(&format!("title = \"{}\"\n", toml_escape_one(t)));
        }
        fs::write(&book_toml_path, content).map_err(|e| e.to_string())?;
    }

    // Create src/SUMMARY.md and src/chapter_1.md if not present
    let summary = src_dir.join("SUMMARY.md");
    if !summary.exists() {
        fs::write(&summary, SUMMARY_MD).map_err(|e| e.to_string())?;
    }
    let chap = src_dir.join("chapter_1.md");
    if !chap.exists() {
        fs::write(&chap, CHAPTER_MD).map_err(|e| e.to_string())?;
    }

    // Create the build dir (default "book")
    let book_dir = dir.join("book");
    fs::create_dir_all(&book_dir).map_err(|e| e.to_string())?;

    util::log_info("mdbook_driver::init", "Creating a new book with stub content");
    println!();
    println!("All done, no errors...");

    Ok(())
}

fn toml_escape_one(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn toml_escape_str(s: &str) -> Vec<String> {
    vec![toml_escape_one(s)]
}

fn copy_default_theme(_theme_dir: &Path) -> Result<(), String> {
    // We don't have the actual theme files. We create a stub to allow the theme
    // directory to be populated. In a real reimplementation these would be embedded.
    // Keep the directory empty aside from minimal marker files so downstream
    // behavior still observes a theme directory.
    Ok(())
}
