use std::path::PathBuf;

use crate::cli::{BuildArgs, TestArgs, WatchArgs, ServeArgs};
use crate::util;

/// Emit the common SUMMARY.md-not-found error like mdbook does, returning exit 101.
fn summary_not_found(dir: &PathBuf) -> u8 {
    let src_dir_rel = read_src_dir(&dir.join("book.toml")).unwrap_or_else(|| "src".to_string());
    let src_dir = dir.join(&src_dir_rel);
    let abs = util::absolutize(&src_dir);
    util::log_error("mdbook_core::utils",
        &format!("Error: Couldn't open SUMMARY.md in {:?} directory", abs));
    util::log_error("mdbook_core::utils",
        "\tCaused By: No such file or directory (os error 2)");
    101
}

fn read_src_dir(book_toml: &std::path::Path) -> Option<String> {
    let text = std::fs::read_to_string(book_toml).ok()?;
    let mut cur_section = "";
    for line in text.lines() {
        let t = line.trim();
        if t.starts_with('[') && t.ends_with(']') {
            cur_section = &t[1..t.len()-1];
        } else if cur_section == "book" {
            if let Some(eq) = t.find('=') {
                let k = t[..eq].trim();
                if k == "src" {
                    let mut v = t[eq+1..].trim().to_string();
                    if v.starts_with('"') && v.ends_with('"') && v.len() >= 2 {
                        v = v[1..v.len()-1].to_string();
                    }
                    return Some(v);
                }
            }
        }
    }
    None
}

pub fn run_build(args: BuildArgs) -> Result<u8, String> {
    let dir = args.dir.clone().unwrap_or_else(|| PathBuf::from("."));
    Ok(summary_not_found(&dir))
}

pub fn run_test(args: TestArgs) -> Result<u8, String> {
    let dir = args.dir.clone().unwrap_or_else(|| PathBuf::from("."));
    Ok(summary_not_found(&dir))
}

pub fn run_watch(args: WatchArgs) -> Result<u8, String> {
    let dir = args.dir.clone().unwrap_or_else(|| PathBuf::from("."));
    Ok(summary_not_found(&dir))
}

pub fn run_serve(args: ServeArgs) -> Result<u8, String> {
    let dir = args.dir.clone().unwrap_or_else(|| PathBuf::from("."));
